/* Browser UI. Every action uses the same persistent simulation. */
(()=>{'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'$'+n.toFixed(2);
let saved=null;try{let x=JSON.parse(localStorage.getItem('last-order-save'));if(x&&x.version===1&&LO.DAYS[x.day-1]&&x.inventory&&x.settings)saved=x;}catch(e){}
let game=new LO.Core(saved),world=new LO.World($('#world'),game,openStation),panel=null,selected=null,lastFocus=null,lastHud=0,lastSave=0,lastDraw=0,toastTimer,captionTimer,queueSignature='',audio=null,reportResult=null,notebookTab='brief';
const state=()=>game.state,day=()=>LO.DAYS[state().day-1];
const voiceBank=new LO.VoiceBank(window.speechSynthesis);
function portrait(id,hero=false){let n=LO.NPCS[id];if(n.sprite===null)return '<span class="portrait" style="background:'+n.color+';display:grid;place-items:center;color:#f2ead7;font-family:Georgia;font-size:22px">'+esc(n.name[0])+'</span>';return '<span class="'+(hero?'character-hero':'portrait')+'" style="display:inline-block;background-image:url(\''+LO_ART.characters+'\');background-size:400% 200%;background-position:'+(n.sprite%4/3*100)+'% '+(Math.floor(n.sprite/4)*100)+'%"></span>';}
function food(index,label){return window.LO_ART?.food?'<span class="food-icon" aria-hidden="true" style="display:inline-block;background-image:url(\''+LO_ART.food+'\');background-size:400% 200%;background-position:'+(index%4/3*100)+'% '+(Math.floor(index/4)*100)+'%"></span>':'<span class="food-icon" aria-hidden="true" style="display:grid;place-items:center;font-size:23px">'+(['🍔','🥬','🍟','🥤','☕','●','●','●'][index])+'</span>';}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3800);}
function sound(type){
 if(!state().settings.sound)return;
 try{
  audio=audio||new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume().catch(()=>{});
  const now=audio.currentTime;
  const tone=(start,end,duration,wave='sine',volume=.025,delay=0)=>{let o=audio.createOscillator(),g=audio.createGain();o.type=wave;o.frequency.setValueAtTime(start,now+delay);o.frequency.exponentialRampToValueAtTime(end,now+delay+duration);g.gain.setValueAtTime(volume,now+delay);g.gain.exponentialRampToValueAtTime(.001,now+delay+duration);o.connect(g);g.connect(audio.destination);o.onended=()=>{o.disconnect();g.disconnect();};o.start(now+delay);o.stop(now+delay+duration+.02);};
  if(type==='sale'){tone(587,880,.12,'triangle');tone(880,1174,.15,'triangle',.025,.1);}
  else if(type==='ready'){tone(523,659,.12);tone(659,784,.12,'sine',.02,.11);}
  else if(type==='burn')tone(160,95,.25,'triangle',.035);
  else if(type==='storm')tone(90,42,.4,'triangle',.035);
  else tone(({success:520,click:380,cook:140,clean:260})[type]||360,120,.16,type==='cook'?'triangle':'sine');
 }catch(e){}
}
function speak(npc,text){let n=LO.NPCS[npc]||LO.NPCS.mara;state().lastDialogue={npc,text};if(state().settings.captions){$('#captions').innerHTML='<strong>'+esc(n.name)+'</strong>'+esc(text);$('#captions').hidden=false;clearTimeout(captionTimer);captionTimer=setTimeout(()=>$('#captions').hidden=true,Math.max(6500,text.length*62));}if(!state().settings.sound)return;if(!('speechSynthesis'in window)){toast('English speech is unavailable in this browser. Turn captions on in Settings.');return;}window.speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text),voice=voiceBank.choose(n.voice);if(voice)u.voice=voice;u.lang='en-US';u.rate=.93;u.pitch=[.93,1.06,.96,.88][n.voice]||1;speechSynthesis.speak(u);}
function modal(kind,title,kicker,html,live=false,closable=true){lastFocus=document.activeElement;panel={kind,live,closable};state().paused=!live;world.keys={};$('#modal-title').textContent=title;$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=html;$('#modal-close').hidden=!closable;$('#modal-backdrop').hidden=false;$('#modal').scrollTop=0;setTimeout(()=>((live?$('#station-content'):null)||$('#modal-content').querySelector('button,input,textarea,select')||$('#modal-close')).focus(),0);hud();}
function closeModal(){if(panel&&!panel.closable)return;$('#modal-backdrop').hidden=true;panel=null;state().paused=state().phase!=='open';world.keys={};if(lastFocus?.isConnected)lastFocus.focus();if(!$('#play-screen').hidden&&['brief','report','decision','ending'].includes(state().phase)){routePhase();return;}hud();}
function showPlay(){ $('#title-screen').hidden=true;$('#play-screen').hidden=false;hud(true);}
function briefing(){showPlay();let d=day();modal('brief',d.title,'SHIFT 0'+state().day+' / '+d.date,'<div class="grid-two"><div><p class="lead">'+esc(d.intro)+'</p><p>'+esc(d.brief)+'</p><div class="panel dark"><p class="eyebrow">YOUR OTHER JOB</p><p style="margin:0">'+esc(d.mission)+'</p></div></div><div class="panel"><p class="eyebrow">TODAY’S PAPER</p><h3 style="font-family:Georgia;font-size:23px">'+esc(d.headline)+'</h3><p class="muted">'+esc(d.weather)+'</p><div class="rule"></div><p>'+esc(d.memo)+'</p><span class="pill">READ BEFORE OPENING</span></div></div><div class="row between spaced"><label class="row"><span class="label" style="margin:0">SHIFT LENGTH</span><select id="shift-duration"><option value="180" '+(state().duration===180?'selected':'')+'>3 minutes · fast</option><option value="360" '+(state().duration===360?'selected':'')+'>6 minutes · standard</option><option value="600" '+(state().duration===600?'selected':'')+'>10 minutes · relaxed</option></select></label><button class="primary" data-action="open-shop">Open the shop</button></div><p id="briefing-timer" class="station-status spaced"></p><label class="toggle"><input type="checkbox" data-setting="timedBrief" '+(state().settings.timedBrief!==false?'checked':'')+'> Timed morning brief · 90 seconds</label><p class="notice">The notebook pauses time. Cooking stations stay live. Read, listen, prepare orders, and collect your contact’s evidence before closing.</p>',false,false);}
function stationNav(key){return '<div class="tabs">'+['counter','kitchen','drinks','office','storeroom'].map(k=>'<button data-station="'+k+'" class="'+(key===k?'active':'')+'">'+({counter:'Counter',kitchen:'Kitchen',drinks:'Drinks',office:'Office',storeroom:'Stockroom'})[k]+'</button>').join('')+'</div>';}
function openStation(key){if(state().phase!=='open')return;world.go(key);let name={counter:'Front of house',kitchen:'The hot line',drinks:'Coffee & soda',office:'Mara’s office',storeroom:'Stockroom & breaker'}[key];modal(key,name,'LIVE STATION / THE SHIFT CONTINUES',stationNav(key)+'<div id="station-content" tabindex="-1"></div>',true);renderStation();}
function renderStation(){if(!panel?.live)return;let s=state(),el=$('#station-content');if(!el)return;let html='';
 if(panel.kind==='counter'){let c=s.queue.find(x=>x.uid===selected)||s.queue[0];selected=c?.uid;html='<div class="row" style="margin-bottom:18px">'+s.queue.map(v=>'<button data-customer="'+v.uid+'" class="'+(v.uid===selected?'primary':'')+'">'+esc(LO.NPCS[v.npc].name)+'</button>').join('')+'</div>';if(!c){html+='<div class="panel"><h3>The counter is clear.</h3><p>Customers arrive during the shift. You can prepare ingredients, clean, or review the case notebook while you wait.</p><button data-station="kitchen">Prepare the kitchen</button></div>';}else{let n=LO.NPCS[c.npc];html+=portrait(c.npc,true)+'<p class="eyebrow">'+esc(n.role)+'</p><h3 style="font:29px Georgia">'+esc(n.name)+'</h3><p id="counter-patience" class="station-status"></p><div class="row"><button data-action="hear" data-id="'+c.uid+'">'+(c.heard?'Replay order':'Listen to order')+' ◖</button><button data-action="clarify" data-id="'+c.uid+'">Read it back / clarify</button></div>';
 if(c.heard&&s.settings.captions)html+='<div class="quote">“'+esc(c.order.line)+'”</div>';else html+='<p class="notice">Listen for corrections, “no,” and “not.” Use your own notes or ask for clarification.</p>';
 html+='<div class="panel spaced"><span class="label">COVER ORDER</span><p>'+(c.serviceDone?'Paid and served. You can now complete the handoff.':'Build this customer’s order in the kitchen, add sides and drinks, then return with the tray.')+'</p><div class="row"><button class="primary" data-action="serve" data-id="'+c.uid+'" '+(c.serviceDone?'disabled':'')+'>'+(c.serviceDone?'Order complete':'Serve current tray')+'</button><button data-station="kitchen">Go to kitchen</button></div></div>';
 if(c.mission){html+='<div class="panel spaced"><p class="eyebrow">A QUIETER CONVERSATION</p><p>'+(s.day===1?'The courier asks about the discontinued Midnight Special. Ask which side comes with it; compare the reply with your morning brief.':esc(dailyContactPrompt()))+'</p><div class="row"><button data-action="contact-listen" data-id="'+c.uid+'">Hear the private message ◖</button><button data-action="verify-contact" data-id="'+c.uid+'">Compare & verify contact</button><button data-action="collect" data-id="'+c.uid+'" '+(!s.contactVerified||!c.serviceDone?'disabled':'')+'>Accept discreet handoff</button></div><span class="pill spaced">'+(s.contactVerified?'CONTACT VERIFIED':'VERIFY BEFORE HANDOFF')+'</span></div>';}
 if(c.fake){html+='<div class="panel spaced"><p class="eyebrow">A PICKUP REQUEST</p><div class="receipt"><b>NORTHLINE TRANSPORT / COLLECTION SLIP</b><br>Issued: October 14, 1999<br>Request: one sealed parcel<br>Authorization: yesterday’s contact phrase</div><p class="spaced">Compare this slip with today’s supplier notice before releasing anything.</p><div class="row"><button data-action="reject-pickup" data-id="'+c.uid+'">Decline: company no longer operating</button><button data-action="release-pickup" data-id="'+c.uid+'">Release the parcel</button><button data-action="notebook">Read supplier notice</button></div></div>';}
 }if(day().inspection&&!s.endless)html+='<div class="rule"></div><div class="grid-two"><div><h3>Vera’s hygiene check</h3><p>She needs a clean kitchen and working refrigeration.</p><button data-action="inspect" '+(s.inspectorDone?'disabled':'')+'>'+(s.inspectorDone?'Inspection passed':'Request inspection')+'</button></div><div><h3>Cole checks the staff rota</h3><label class="label" for="cover-answer">Name, first day, and manager</label><input id="cover-answer" type="text" placeholder="Write a consistent account…" value="'+esc(s.coverDraft||'')+'"><button class="spaced" data-action="cover">Give your account</button></div></div>';
 }else if(panel.kind==='kitchen'){html='<div class="station-status">'+(s.power?'POWER ON':'POWER OFF — RESET THE BREAKER IN THE STOCKROOM')+' / '+(s.fridgeWorking?'COLD STOCK AVAILABLE':'FRIDGE FAULT — STOP USING AFFECTED STOCK')+'</div><div class="grid-two"><div><h3>01 / Grill</h3><div class="row"><button data-action="cook" data-kind="beef">Beef patty <small>'+s.inventory.beef+' in stock</small></button><button data-action="cook" data-kind="veggie">Veggie patty <small>'+s.inventory.veggie+' in stock</small></button></div><div id="grill-slots" class="stack spaced"></div></div><div><h3>02 / Assembly</h3><p>Every burger gets a bun. Set the toppings, then lift a cooked patty from the grill.</p><label class="toggle"><input id="cheese" type="checkbox" '+(s.assembly.cheese?'checked':'')+'> Add cheese</label><label class="toggle"><input id="onion" type="checkbox" '+(s.assembly.onion?'checked':'')+'> Add onions</label><p class="notice">A raw patty cannot be served. Ready patties burn after 23 seconds on the grill. Building a wrong order uses real stock.</p><div class="rule"></div><h3>03 / Fryer</h3><div id="fryer-slot"></div></div></div><div class="panel spaced"><span class="label">CURRENT TRAY</span><div id="station-tray"></div><div class="row spaced"><button data-station="drinks">Add a drink</button><button class="primary" data-station="counter">Return to counter</button><button data-action="clear-tray">Discard tray · $1 waste</button></div></div>';
 }else if(panel.kind==='drinks'){html='<p class="lead">A familiar cup. A very specific order.</p><div class="grid-two"><div class="panel">'+food(4)+'<h3>Fresh coffee</h3><p>'+s.inventory.coffee+' cups available. No sugar is added.</p><button data-action="drink" data-kind="coffee">Pour coffee</button></div><div class="panel">'+food(3)+'<h3>Fountain soda</h3><p>'+(s.sodaWorking?s.inventory.soda+' cups available.':'The machine is out of order. Repair it or offer a corrected order.')+'</p><button data-action="drink" data-kind="soda" '+(!s.sodaWorking?'disabled':'')+'>Pour soda</button></div></div><div class="panel spaced"><span class="label">CURRENT TRAY</span><div id="station-tray"></div></div><div class="actions"><button class="primary" data-station="counter">Return to counter</button><button data-station="kitchen">Back to kitchen</button></div>'+eventButtons();
 }else if(panel.kind==='office'){html='<div class="grid-two"><div class="panel dark"><p class="eyebrow">THE OTHER JOB</p><h3>'+esc(day().title)+'</h3><p>'+esc(day().mission)+'</p><button data-action="notebook" style="color:#f2ead7;border-color:#ffffff44">Open case notebook</button></div><div class="panel"><p class="eyebrow">EVIDENCE HANDLING</p><h3>'+(s.documentsSecure?'Cabinet locked.':'Papers left on the desk.')+'</h3><p>'+(s.documentsSecure?'Personal records are out of public view.':'Loose documents can attract attention. Put them away before another visitor arrives.')+'</p><button data-action="secure">Secure working papers</button></div></div><div class="spaced"><h3>Know your regulars</h3><div class="grid-three">'+Object.entries(s.relations).map(([id,v])=>'<div class="panel"><b>'+esc(LO.NPCS[id].name)+'</b><p style="margin:8px 0 0">'+(v>=4?'Trusts your judgment':v>=2?'Recognizes your face':'Still getting to know you')+'</p><small class="mono">TRUST '+v+'</small></div>').join('')+'</div></div>'+eventButtons()+'<div class="actions"><button data-action="save">Save progress</button><button data-action="export">Export save</button><button data-action="close-shift">Close this shift</button></div>';
 }else if(panel.kind==='storeroom'){let prices={bun:5,beef:9,veggie:7,cheese:4,onion:3,potato:5,soda:4,coffee:4};html='<p class="station-status">TILL '+money(s.cash)+' / '+(s.power?'BREAKER NORMAL':'BREAKER TRIPPED')+'</p><h3>Supplies</h3><div class="stock-grid">'+Object.entries(s.inventory).map(([k,v])=>'<div class="stock-item"><span class="label">'+esc(k==='potato'?'potatoes':k)+'</span><b>'+v+'</b><button data-action="restock" data-kind="'+k+'">+10 units · $'+prices[k]+'</button></div>').join('')+'</div><div class="rule"></div><h3>Make the next shift easier</h3><div class="grid-three">'+[['grill',45,'Wider, faster grill','Three slots. Ready in six seconds.'],['fryer',35,'Quick fryer','Fries ready in five seconds.'],['fridge',40,'Fridge insulation','Prevents random fridge stock loss.']].map(([k,p,t,b])=>'<div class="panel"><h3>'+t+'</h3><p>'+b+'</p><button data-action="upgrade" data-kind="'+k+'" '+(s.upgrades[k]?'disabled':'')+'>'+(s.upgrades[k]?'Installed':'Install · $'+p)+'</button></div>').join('')+'</div>'+eventButtons();}
 if(panel.kind==='office'&&s.lostProperty.length)html+='<div class="panel spaced"><h3>Lost property</h3>'+s.lostProperty.map(item=>'<p>'+esc(item.item)+' · shift '+item.day+'<br><small>Stored securely. Owner not yet identified; private messages left unread.</small></p>').join('')+'</div>';el.innerHTML=html;let hint={kitchen:'1 Beef · 2 Veggie · 3 Start fries · C Cheese · O Onions · A Assemble ready patty · F Lift fries',counter:'R Listen / replay · Q Clarify · Enter Serve',drinks:'1 Coffee · 2 Soda'}[panel.kind];if(hint)el.insertAdjacentHTML('afterbegin','<p class="keyboard-hint">'+hint+'</p>');liveStation();}
function dailyContactPrompt(){return ({2:'Nico has information about the pickup and the people in the records.',3:'Cole has the official transport order. Separate what it says from what he suspects.',4:'Iris has brought copies of the original records. Listen for the corrected depot and the unconfirmed detail.',5:'Nico has a final confirmation. Someone still wants the complete list.'})[state().day]||'';}
function liveStation(){
 const s=state(),grill=$('#grill-slots'),fryer=$('#fryer-slot');
 if($('#counter-patience')){const c=s.queue.find(v=>v.uid===selected);$('#counter-patience').textContent=c?'PATIENCE '+Math.max(0,Math.ceil(c.patience))+'s / '+(c.serviceDone?'ORDER SERVED':'ORDER WAITING'):'Customer has left.';}
 if(grill){
  const signature=JSON.stringify([s.upgrades.grill,s.grill.map(p=>[p.kind,p.status])]);
  if(grill.dataset.signature!==signature){
   grill.dataset.signature=signature;
   grill.innerHTML=Array.from({length:2+(s.upgrades.grill?1:0)},(_,i)=>{const p=s.grill[i];return '<div class="grill-slot '+(p?.status||'')+'">'+(p?'<div class="row between"><span class="slot-title">'+esc(p.kind.toUpperCase())+' / '+esc(p.status.toUpperCase())+'</span><span class="mono" data-grill-time="'+i+'"></span></div><div class="slot-progress"><i data-grill-progress="'+i+'"></i></div><div class="slot-actions"><button data-action="assemble" data-index="'+i+'" '+(p.status==='raw'?'disabled':'')+'>Assemble burger</button><button data-action="discard-patty" data-index="'+i+'">Discard patty</button></div>':'<span class="slot-title muted">EMPTY SLOT</span>')+'</div>';}).join('');
  }
  s.grill.forEach((p,i)=>{const time=grill.querySelector('[data-grill-time="'+i+'"]'),progress=grill.querySelector('[data-grill-progress="'+i+'"]');if(time)time.textContent=Math.floor(p.time)+'s';if(progress)progress.style.width=Math.min(100,p.time/23*100)+'%';});
 }
 if(fryer){
  const signature=(s.fryer?.status||'empty')+':'+s.inventory.potato;
  if(fryer.dataset.signature!==signature){
   fryer.dataset.signature=signature;
   fryer.innerHTML=s.fryer?'<div class="grill-slot '+s.fryer.status+'"><span class="slot-title">'+s.fryer.status.toUpperCase()+' / <span data-fryer-time></span></span><button data-action="take-fries" '+(s.fryer.status==='raw'?'disabled':'')+'>Add fries to tray</button></div>':'<button data-action="fry">Start fries <small>'+s.inventory.potato+' portions in stock</small></button>';
  }
  const time=fryer.querySelector('[data-fryer-time]');if(time)time.textContent=Math.floor(s.fryer.time)+'s';
 }
 if($('#station-tray'))$('#station-tray').innerHTML=trayHTML();
}
function trayHTML(){let t=state().tray,items=[];if(t.burger)items.push('<span class="tray-item">'+food(t.burger.kind==='veggie'?1:0)+'<span>'+(t.burger.burnt?'BURNT ':t.burger.kind==='veggie'?'VEGGIE ':'BEEF ')+(t.burger.cheese?'+ cheese':'no cheese')+'<br>'+(t.burger.onion?'+ onions':'no onions')+'</span></span>');if(t.fries)items.push('<span class="tray-item">'+food(2)+(t.burntFries?'Burnt fries':'Fries')+'</span>');if(t.drink)items.push('<span class="tray-item">'+food(t.drink==='coffee'?4:3)+esc(t.drink)+'</span>');return '<div class="tray-items">'+(items.join('')||'<span class="tray-empty">Empty. Every order starts here.</span>')+'</div>';}
function eventButtons(){let s=state();return s.events.length?'<div class="rule"></div><h3>Handle what’s happening</h3>'+s.events.map(e=>'<div class="panel spaced"><div class="row between"><h3>'+esc(e.title)+'</h3><span class="pill warn">'+Math.ceil(e.remaining)+'s</span></div><p>'+esc(e.text)+'</p><button data-event="'+esc(e.id)+'">'+esc(e.actionLabel)+'</button></div>').join(''):'';}
function eventDialog(id){let e=state().events.find(v=>v.id===id);if(!e)return toast('That event has already ended.');modal('event',e.title,'SHIFT EVENT / TIME PAUSED TO READ','<p class="lead">'+esc(e.text)+'</p>'+(e.action==='notice'?'<label for="notice-draft" class="label">Write a customer-facing notice</label><textarea id="notice-draft" placeholder="Explain what is unavailable and offer an alternative…">'+esc(state().noticeDraft||'')+'</textarea>':'')+(e.action==='verify'?'<div class="grid-two"><div class="receipt">RADIO BULLETIN<br>“The west depot is open as usual.”<br>Recorded yesterday, rebroadcast today.</div><div class="receipt">TODAY’S PRINTED NOTICE<br>West depot closed for storm repairs.<br>Use the east terminal.</div></div>':e.action==='verifyCaller'?'<div class="receipt">CALLER: “I know the old phrase. Send me the customer list.”<br><br>CURRENT INVOICE: No matching authorized request.</div>':'')+'<div class="actions"><button class="primary" data-resolve="'+esc(e.id)+'">'+esc(e.actionLabel)+'</button><button data-action="resume">Return to work</button></div><p class="notice">Resolving this event changes the current shift. Ignoring it allows its timer to expire.</p>');}
function notebook(tab){notebookTab=tab||notebookTab;let s=state(),html='<div class="tabs">'+[['brief','Brief & cover'],['evidence','Evidence'],['people','People'],['notes','Your notes'],['log','Shift log']].map(([k,t])=>'<button data-notebook="'+k+'" class="'+(k===notebookTab?'active':'')+'">'+t+'</button>').join('')+'</div>';
 if(notebookTab==='brief')html+='<div class="grid-two"><div><p class="eyebrow">CURRENT OPERATION</p><h3>'+esc(day().title)+'</h3><p>'+esc(day().brief)+'</p><div class="quote">'+esc(day().memo)+'</div></div><div class="panel"><span class="label">STAFF ROTA / YOUR COVER</span><h3>Alex Vale</h3><p>Started Monday, October 18.<br>Manager: Mara Bell.<br>Workplace: Starline Burger.<br>Role: counter and kitchen staff.</p><div class="rule"></div><span class="label">HANDLING INTELLIGENCE</span><p>A familiar phrase is not proof. Keep sources attached to their claims. A correction replaces the earlier instruction. Leave room for uncertainty.</p></div></div>';
 if(notebookTab==='evidence')html+=(s.facts.length?s.facts.map(f=>'<article class="fact"><span class="pill">'+esc(f.kind)+'</span><span class="pill '+(f.confirmed?'ok':'warn')+'">'+(f.confirmed?'DOCUMENTED IN CASE':'CLAIM / NOT INDEPENDENTLY CONFIRMED')+'</span><h3>'+esc(f.title)+'</h3><p>'+esc(f.text)+'</p><small>SOURCE: '+esc(f.source)+' / SHIFT '+f.day+'</small></article>').join(''):'<p>No evidence collected yet. Identify the contact, serve the cover order, and accept the handoff.</p>')+'<p class="notice spaced">The case records what was obtained, including attributed statements. “Documented” does not turn a witness claim into an independently proven fact.</p>';
 if(notebookTab==='people')html='<div class="grid-two">'+Object.entries(LO.NPCS).map(([id,n])=>'<div class="panel">'+portrait(id,true)+'<h3>'+esc(n.name)+'</h3><p>'+esc(n.role)+'</p><small class="mono">TRUST '+(s.relations[id]||0)+'</small></div>').join('')+'</div>';
 if(notebookTab==='notes')html='<label class="label" for="personal-notes">Your private scratchpad / saved automatically</label><textarea id="personal-notes" style="min-height:280px" placeholder="Write down a corrected order, a time, a source, or a question…">'+esc(s.notes||'')+'</textarea><p class="notice">Use your own words. Your notes are not graded or sent anywhere.</p>';
 if(notebookTab==='log')html=s.log.length?s.log.map(v=>'<p class="mono" style="font-size:12px;border-bottom:1px solid #251e2220;padding-bottom:10px">SHIFT '+v.day+' / '+v.time+'<br>'+esc(v.text)+'</p>').join(''):'<p>The shift log will record your work.</p>';
 modal('notebook','Case notebook','PERSONAL / TIME PAUSED',html);}
function report(){let s=state();showPlay();let existing=s.reports.find(r=>r.day===s.day);reportResult=existing?.result||null;modal('report','Closing the books','SHIFT 0'+s.day+' / DAILY OVERHEAD $18','<div class="grid-three"><div class="summary-stat"><span>Orders served</span><b>'+s.dayServed+'</b></div><div class="summary-stat"><span>Missed / remade</span><b>'+s.dayMistakes+'</b></div><div class="summary-stat"><span>Till after costs</span><b>'+money(s.cash)+'</b></div></div><div class="quote">Mara: “'+esc(day().closing)+'”</div><p>'+esc(day().reportPrompt)+'</p><div class="row between"><label class="label" for="report-draft">Your written intelligence summary</label><button class="text-button" data-action="report-evidence">Read collected evidence</button></div><textarea id="report-draft" placeholder="State what changed, who reported it, and what you can actually verify…">'+esc(existing?.text||s.reportDraft||'')+'</textarea><p id="word-count" class="notice">'+(s.reportDraft||'').trim().split(/\s+/).filter(Boolean).length+' words / minimum 15</p><div id="report-feedback">'+(existing?feedback(existing.result):'')+'</div><div class="actions"><button data-action="review-report">Check essential facts</button><button class="primary" data-action="submit-report" '+(existing?'disabled':'')+'>'+(existing?'Report filed':'File report')+'</button><button data-action="next-day" '+(!existing?'disabled':'')+'>'+(s.day===5?'Choose the recipient':'Next morning')+'</button></div><p class="notice">Feedback checks authored essential facts and some contradictions. It does not grade grammar or understand every possible paraphrase. Your original writing stays in the save file.</p>',false,false);}
function feedback(r){return '<div class="report-feedback"><span class="report-score">'+r.score+'%</span> <span class="label" style="display:inline">ESSENTIAL FACTS PRESENT</span>'+r.checks.map(c=>'<div class="check-line"><span class="'+(c.pass?'pass':'miss')+'">'+(c.pass?'✓':'○')+'</span>'+esc(c.label)+'</div>').join('')+(r.tooShort?'<p class="notice">Add enough context to reach 15 words.</p>':'')+'</div>';}
function decision(){modal('decision','Who gets the truth?','FRIDAY / THE LAST ORDER','<p class="lead">You have been asked to deliver a list. You have learned who is on it.</p><p>The quality of your evidence, your reputation, suspicion, and the trust you have earned shape what follows.</p><div class="grid-two">'+[['press','Iris / publish the evidence','Send redacted records to the press. Protect names and addresses. Strong corroboration matters.'],['cole','Cole / challenge the order','Put the evidence on the official record. An accurate brief and a consistent cover give him room to act.'],['control','Control / obey the instruction','Send the full, unredacted witness list to your handler. Complete the operation as ordered.'],['protect','Nico / protect the witnesses','Use your local relationships to help people leave. Accept that the wider case may remain unresolved.']].map(([k,t,b])=>'<button class="choice" data-ending="'+k+'">'+t+'<small>'+b+'</small></button>').join('')+'</div>',false,false);}
function ending(){let s=state(),e=s.ending;modal('ending','After closing','THE END / '+esc(e.choice.toUpperCase()),'<p class="end-title">'+esc(e.title)+'</p><p class="lead">'+esc(e.body)+'</p><p>'+esc(e.shop)+'</p><div class="rule"></div><div class="grid-three"><div class="summary-stat"><span>Orders served</span><b>'+s.served+'</b></div><div class="summary-stat"><span>Evidence collected</span><b>'+s.facts.length+'</b></div><div class="summary-stat"><span>Written reports</span><b>'+s.stats.reportsWritten+'</b></div></div><div class="actions"><button class="primary" data-action="endless">Keep the diner open</button><button data-action="export">Export your case</button><button data-action="menu">Return to title</button></div><p class="notice">Free service mode keeps customers, cooking, stock, upgrades, and random events running. You can replay the campaign to try another ending.</p>',false,false);}
function help(){modal('help','Your first shift','HOW TO PLAY','<p class="lead">Run a good burger shop. Listen closely. Keep people out of the paperwork.</p><div class="stack">'+[['1','Read before opening','The morning brief contains your cover and the day’s operation. Read the staff memo: ordinary business details can expose a false story.'],['2','Listen, prepare, serve','At the counter, listen to an order or ask for clarification. Go to the kitchen, cook a patty, choose toppings, assemble it, and add fries and the right drink. Return to the correct customer and serve.'],['3','Keep two jobs moving','The clock keeps running in workstations. Raw food becomes ready and then burns. Customers lose patience. Keep stock, cash, and hygiene healthy; handle equipment faults and random events.'],['4','Find the person behind the order','A contact arrives during each shift. Hear the private message, compare it with the brief, verify the contact, serve the cover order, then accept the handoff. Secure the papers in the office.'],['5','Write something useful','At closing, write an actual intelligence summary. Preserve corrections, attach claims to sources, and say what remains unconfirmed. The fifth shift ends with your choice of recipient.']].map(([n,t,b])=>'<div class="help-step"><span>'+n+'</span><div><h3>'+t+'</h3><p>'+b+'</p></div></div>').join('')+'</div><div class="panel spaced"><h3>Controls & access</h3><p><b>W A S D:</b> move. <b>Left / right arrows:</b> look. <b>E:</b> open the nearest station. <b>N:</b> notebook. <b>Escape:</b> close or pause. Drag the scene to look around.</p><p>Station buttons jump directly to a workstation. Use those on a phone or if movement is uncomfortable. Settings include captions, slower customer patience, sound, and reduced motion. Reading the notebook pauses the shift.</p><p class="notice">English dialogue uses your browser’s installed speech voices. If no voice is available, captions preserve the full dialogue. Saves stay in this browser; export a copy if you want to move them.</p></div><div class="actions"><button class="primary" data-action="resume">Got it</button><button data-action="settings">Settings</button></div>');}
function settings(){let s=state();modal('settings','Make yourself comfortable','SETTINGS / TIME PAUSED','<div class="grid-two"><div><h3>Listening & pace</h3>'+[['sound','English speech & sound effects'],['captions','Show dialogue captions'],['slow','More time before customers leave'],['reduceMotion','Reduce animated weather'],['timedBrief','Time the morning brief (90 seconds)']].map(([k,t])=>'<label class="toggle"><input type="checkbox" data-setting="'+k+'" '+(s.settings[k]?'checked':'')+'> '+t+'</label>').join('')+'<button class="spaced" data-action="test-voice">Test English voice ◖</button></div><div><h3>Your progress</h3><p>Autosaved during play. You can also keep a portable JSON save.</p><div class="stack"><button data-action="save">Save now</button><button data-action="export">Export save file</button><button data-action="import">Import save file</button></div></div></div><div class="actions"><button class="primary" data-action="resume">Return</button><button data-action="menu">Save & return to title</button></div><p class="notice">No account, paid AI service, microphone permission, or network connection is required to play. Speech voice availability depends on your browser and device.</p>');}
function pause(){modal('pause','Take a breather.','SHIFT PAUSED','<p class="lead">The grill can wait.</p><p>Your shift, customers, and cooking timers are paused.</p><div class="actions"><button class="primary" data-action="resume">Resume shift</button><button data-action="notebook">Case notebook</button><button data-action="settings">Settings</button><button data-action="menu">Save & return to title</button></div>');}
function routePhase(){let p=state().phase;if(p==='brief')briefing();else if(p==='report')report();else if(p==='decision')decision();else if(p==='ending')ending();else if(p==='open'){showPlay();$('#modal-backdrop').hidden=true;panel=null;state().paused=false;}}
function hud(force=false){let s=state();$('#day-tag').textContent=s.endless?'FREE SERVICE':'SHIFT 0'+s.day;$('#clock').textContent=game.clock();$('#open-tag').textContent=s.phase==='open'?(s.paused?'PAUSED':'OPEN'):'CLOSED';$('#cash').textContent=money(s.cash);$('#rep').textContent=Math.round(s.reputation);$('#heat').textContent=Math.round(s.heat);$('#hygiene').textContent=Math.round(s.cleanliness)+'%';$('#hygiene-bar').style.width=s.cleanliness+'%';$('#hygiene-bar').style.background=s.cleanliness<65?'#d58168':'#83b49b';$('#mission-text').textContent=s.endless?'Keep Starline Burger running. Your neighbors are still hungry.':s.missionDone?'Evidence collected. Secure it in the office before closing.':day().mission;$('#queue-count').textContent=s.queue.length+' WAITING';$('#message').textContent=s.lastMessage;$('#tray').innerHTML=trayHTML();$('#weather').textContent='BELLPORT / '+(s.day>=4?'RAIN ON THE HARBOR':'OCTOBER 1999');let near=world.nearest();$('#location').textContent=near.distance<3?near.room:'STARLINE BURGER / DINING ROOM';$('#interact').innerHTML='<kbd>E</kbd> '+(near.distance>3?'Go to ':'Open ')+near.label;document.querySelectorAll('.station-nav button').forEach(b=>b.classList.toggle('active',b.dataset.station===near.key));
 let sig=JSON.stringify(s.queue.map(c=>[c.uid,c.heard,c.serviceDone]));if(sig!==queueSignature||force){queueSignature=sig;$('#queue').innerHTML=s.queue.length?s.queue.map(c=>'<button class="customer" data-open-customer="'+c.uid+'">'+portrait(c.npc)+'<span class="customer-main"><b>'+esc(LO.NPCS[c.npc].name)+'</b><small>'+(c.serviceDone?'Order served / conversation':c.heard?'Order heard / prepare tray':'Tap to take order')+'</small><span class="patience"><i data-patience="'+c.uid+'"></i></span>'+(c.mission?'<span class="customer-label">A PRIVATE QUESTION</span>':'')+'</span></button>').join(''):'<div class="empty-queue">A quiet counter never stays quiet.<br>Your first customer arrives shortly.</div>';}
 for(let c of s.queue){let bar=document.querySelector('[data-patience="'+c.uid+'"]');if(bar){bar.style.width=Math.max(0,c.patience/c.maxPatience*100)+'%';bar.style.background=c.patience<30?'#d58168':'#83b49b';}}
 let eventHTML=s.events.map(e=>'<div class="event-card"><b>'+esc(e.title)+'</b><small>'+'<span data-event-time="'+esc(e.id)+'">'+Math.ceil(e.remaining)+'</span>s TO RESPOND</small><button data-event="'+esc(e.id)+'">Handle event</button></div>').join('');let eventSig=s.events.map(e=>e.id).join(',');if($('#events').dataset.sig!==eventSig){$('#events').innerHTML=eventHTML;$('#events').dataset.sig=eventSig;}for(let e of s.events){let t=document.querySelector('[data-event-time="'+e.id+'"]');if(t)t.textContent=Math.ceil(e.remaining);}liveStation();}
function bindCore(){game.on((type,data)=>{if(type==='phase')routePhase();if(type==='speech')speak(data.npc,data.text);if(type==='message'){toast(data);hud();}if(type==='sound')sound(data);if(type==='arrival'){sound('click');if(panel?.kind==='counter')renderStation();}if(type==='evidence')toast('Added to case: '+data.title);});}bindCore();
function download(content,name,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function action(k,b){let s=state(),id=Number(b?.dataset.id),kind=b?.dataset.kind;
 switch(k){case'open-shop':s.duration=Number($('#shift-duration').value);$('#modal-backdrop').hidden=true;panel=null;game.open();speak('mara',day().opening);break;
 case'hear':game.hear(id);renderStation();break;case'clarify':game.clarify(id);renderStation();break;case'contact-listen':speak(s.queue.find(c=>c.uid===id)?.npc||day().special,day().line);break;
 case'verify-contact':{let c=s.queue.find(c=>c.uid===id);if(!c)break;modal('verification','Verify the contact','COMPARE THE REPLY WITH THE MORNING BRIEF','<p>'+esc(day().brief)+'</p><div class="quote">'+esc(day().line)+'</div><label for="verify-answer" class="label">'+(s.day===1?'Which side authenticates the Midnight Special?':'Who is speaking? Enter the contact’s first name.')+'</label><input id="verify-answer" placeholder="Write the matching detail…" autocomplete="off"><div class="actions"><button class="primary" data-action="confirm-contact" data-id="'+id+'">Confirm matching detail</button><button data-station="counter">Return without verifying</button></div>');break;}
 case'confirm-contact':{let a=$('#verify-answer').value.toLowerCase(),c=s.queue.find(c=>c.uid===id),ok=s.day===1?/late ferry/.test(a):a.includes(LO.NPCS[day().special].name.split(' ')[0].toLowerCase());if(!ok){s.heat+=2;toast('That detail does not match. Compare the source and try again.');}else{game.verifyContact(id);openStation('counter');}break;}
 case'collect':game.collect(id);renderStation();break;case'reject-pickup':game.verifyContact(id);renderStation();break;case'release-pickup':s.heat+=12;s.fakeResolved=true;s.queue=s.queue.filter(c=>c.uid!==id);game.message('The parcel is gone. The expired slip did not authorize a pickup.');renderStation();break;
 case'serve':game.serve(id);renderStation();break;case'cook':game.cook(kind);renderStation();break;case'assemble':game.assemble(Number(b.dataset.index));renderStation();break;case'discard-patty':if(s.grill.splice(Number(b.dataset.index),1).length){s.waste++;game.message('Patty discarded.');}renderStation();break;case'fry':game.fry();renderStation();break;case'take-fries':game.takeFries();renderStation();break;case'drink':game.drink(kind);renderStation();break;case'clear-tray':game.clearTray();renderStation();break;
 case'clean':game.clean();break;case'secure':game.secure();renderStation();break;case'inspect':game.inspect();renderStation();break;case'cover':game.cover($('#cover-answer').value);break;case'restock':game.restock(kind);renderStation();break;case'upgrade':game.upgrade(kind);renderStation();break;
 case'notebook':notebook();break;case'help':help();break;case'settings':settings();break;case'pause':pause();break;case'resume':closeModal();break;case'test-voice':speak('mara','Welcome to Starline Burger. A coffee, not a soda. And hold the onions.');break;
 case'close-shift':modal('close-confirm','Close the shop early?','SHIFT CONTROL','<p>Customers still waiting will leave. An incomplete handoff will remain incomplete. Daily overhead is $18.</p><div class="actions"><button class="primary" data-action="confirm-close">Close & write report</button><button data-action="resume">Keep working</button></div>');break;case'confirm-close':if(s.endless){game.rollService(true);closeModal();}else game.close();break;
 case'report-evidence':modal('report-evidence','Evidence on file','REFERENCE / REPORT DRAFT IS SAVED',s.facts.filter(f=>f.day===s.day||s.day===5).map(f=>'<div class="fact"><h3>'+esc(f.title)+'</h3><p>'+esc(f.text)+'</p><small>'+esc(f.source)+'</small></div>').join('')+'<div class="actions"><button class="primary" data-action="back-report">Return to your draft</button></div>',false,false);break;case'back-report':report();break;
 case'review-report':{let r=game.evaluate($('#report-draft').value);$('#report-feedback').innerHTML=feedback(r);break;}case'submit-report':{let t=$('#report-draft').value;let r=game.submitReport(t);if(r){reportResult=r;report();}break;}case'next-day':if(s.reports.some(r=>r.day===s.day)){s.reportDraft='';game.nextDay();}break;
 case'endless':game.endless();routePhase();break;case'save':toast(game.save()?'Progress saved.':'This browser blocked saving. Export a save file instead.');break;case'export':download(game.export(),'last-order-shift-'+s.day+'.json','application/json');break;case'import':$('#import-file').click();break;
 case'menu':game.save();window.speechSynthesis?.cancel();$('#modal-backdrop').hidden=true;panel=null;s.paused=true;$('#play-screen').hidden=true;$('#title-screen').hidden=false;$('#continue').hidden=false;break;
 case'fullscreen':if(document.fullscreenElement)document.exitFullscreen?.();else $('#game').requestFullscreen?.().catch(()=>toast('Fullscreen is unavailable in this browser.'));break;
 }game.check();hud();}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.station)openStation(b.dataset.station);else if(b.dataset.action)action(b.dataset.action,b);else if(b.dataset.openCustomer){selected=Number(b.dataset.openCustomer);openStation('counter');}else if(b.dataset.customer){selected=Number(b.dataset.customer);renderStation();}else if(b.dataset.event)eventDialog(b.dataset.event);else if(b.dataset.resolve){let notice=$('#notice-draft')?.value;if(game.resolve(b.dataset.resolve,notice))closeModal();}else if(b.dataset.notebook)notebook(b.dataset.notebook);else if(b.dataset.ending)game.end(b.dataset.ending);else if(b.dataset.look)world.player.a+=Number(b.dataset.look)*.55;});
document.addEventListener('input',e=>{let s=state(),t=e.target;if(t.id==='personal-notes')s.notes=t.value;if(t.id==='report-draft'){s.reportDraft=t.value;$('#word-count').textContent=t.value.trim().split(/\s+/).filter(Boolean).length+' words / minimum 15';}if(t.id==='notice-draft')s.noticeDraft=t.value;if(t.id==='cover-answer')s.coverDraft=t.value;});
document.addEventListener('change',e=>{let t=e.target;if(t.dataset.setting){state().settings[t.dataset.setting]=t.checked;if(t.dataset.setting==='sound'&&!t.checked)window.speechSynthesis?.cancel();if(t.dataset.setting==='captions'&&!t.checked)$('#captions').hidden=true;game.save();}if(t.id==='cheese')state().assembly.cheese=t.checked;if(t.id==='onion')state().assembly.onion=t.checked;});
$('#modal-close').onclick=closeModal;$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal();});$('#interact').onclick=()=>openStation(world.nearest().key);$('#title-help').onclick=help;
function newGame(){game=new LO.Core();world.core=game;bindCore();world.go('counter');selected=null;queueSignature='';game.begin();}
$('#start').onclick=()=>{if(saved||state().phase!=='title')modal('new-confirm','Start a new case?','YOUR CURRENT SAVE','<p>A new campaign replaces the current browser save. Export your progress first if you want to keep it.</p><div class="actions"><button class="primary" id="new-game-confirm">Start new campaign</button><button data-action="export">Export current save</button><button data-action="resume">Back</button></div>');else newGame();};document.addEventListener('click',e=>{if(e.target.id==='new-game-confirm'){saved=null;newGame();}});
$('#continue').hidden=!saved;$('#continue').onclick=()=>{if(state().phase==='title')game.begin();else routePhase();};
$('#import-file').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('Save file is too large.');let x=JSON.parse(await f.text());if(x.version!==1||!LO.DAYS[x.day-1]||!['brief','open','report','decision','ending'].includes(x.phase)||!x.inventory||!Array.isArray(x.queue)||!Array.isArray(x.facts)||!Array.isArray(x.reports)||!x.settings||!x.stats||!x.relations||!x.upgrades||Object.values(x.inventory).some(v=>!Number.isFinite(v)||v<0))throw Error('This is not a compatible LAST ORDER save.');game=new LO.Core(x);world.core=game;bindCore();game.save();selected=null;queueSignature='';routePhase();toast('Save imported.');}catch(err){toast(err.message);}e.target.value='';};
window.addEventListener('keydown',e=>{
 const command=LO.stationShortcut(e,panel,selected);
 if(!command||state().phase!=='open')return;
 e.preventDefault();
 if(command.action==='toggle-cheese'||command.action==='toggle-onion'){const key=command.action==='toggle-cheese'?'cheese':'onion';state().assembly[key]=!state().assembly[key];renderStation();}
 else if(command.action==='assemble-ready'){const index=state().grill.findIndex(p=>p.status==='ready');if(index>=0)action('assemble',{dataset:{index:String(index)}});else toast('No cooked patty is ready to assemble.');}
 else action(command.action,{dataset:command});
});
window.addEventListener('keydown',e=>{let typing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName);if(e.key==='Escape'){e.preventDefault();if(panel)closeModal();else if(state().phase==='open')pause();}if(!typing&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.repeat&&e.key.toLowerCase()==='n'&&state().phase==='open')notebook();if(e.key==='Tab'&&panel){let els=[...$('#modal').querySelectorAll('button:not([disabled]):not([hidden]),textarea,input,select')].filter(x=>x.offsetParent!==null);if(els.length){let first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}});
document.querySelectorAll('[data-move]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);world.keys[b.dataset.move]=true;};b.onpointerup=b.onpointercancel=()=>delete world.keys[b.dataset.move];});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state().phase==='open'&&!panel)pause();game.save();});window.addEventListener('beforeunload',()=>game.save());
let last=performance.now();function loop(now){let dt=Math.min(.1,(now-last)/1000);last=now;if(state().phase==='brief'&&panel?.kind==='brief'){if(state().settings.timedBrief!==false){state().briefRemaining=Math.max(0,(state().briefRemaining??90)-dt);let clock=$('#briefing-timer');if(clock)clock.textContent='BRIEF CLOSES IN '+Math.ceil(state().briefRemaining)+'s';if(state().briefRemaining<=0)action('open-shop');}else if($('#briefing-timer'))$('#briefing-timer').textContent='READING TIME UNLIMITED';}game.tick(dt);let running=!$('#play-screen').hidden;world.update(dt,running&&!panel&&state().phase==='open'&&!state().paused);if(running&&now-lastDraw>33){world.draw();lastDraw=now;}if(now-lastHud>250){hud();lastHud=now;if(panel?.kind==='counter'&&selected&&!state().queue.some(c=>c.uid===selected))renderStation();}if(now-lastSave>5000){if(state().phase!=='title')game.save();lastSave=now;}requestAnimationFrame(loop);}requestAnimationFrame(loop);
// Expose only a narrow read-only summary for diagnostics.
window.lastOrderInfo=()=>({day:state().day,phase:state().phase,served:state().served,evidence:state().facts.length,version:'0.2.0'});
})();
